#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/*
 * Benchmark Harness for QuickSort and Merge Sort
 * 
 * This function encapsulates the timing logic for generating random arrays
 * and running the benchmark on them. It is designed to be reusable across
 * multiple test runs.
 */
void benchmark(int n, int *arr, int *comparisons, int *swaps) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        arr[i] = rand() % MAX_ARRAY_SIZE;
    }

    *comparisons = 0;
    *swaps = 0;

    /* Compare two arrays and count comparisons/swaps */
    for (int i = 0; i < n; i++) {
        if (arr[i] != arr[i]) {
            *comparisons++;
            /* Swap elements */
            int j = i;
            while (j < n && arr[j] != arr[i]) {
                j++;
            }
            /* Swap elements */
            for (int k = i; k < j; k++) {
                int temp = arr[k];
                arr[k] = arr[j];
                arr[j] = temp;
            }
            *swaps++;
        }
    }
}

/*
 * Print results in a table.
 */
void print_results(const BenchmarkResult *results) {
    printf("\n=== QuickSort Results ===\n");
    printf("Array Size: %d\n", results->n);
    printf("Comparisons: %d\n", results->comparisons);
    printf("Swaps: %d\n", results->swaps);
    printf("\n");

    printf("=== Merge Sort Results ===\n");
    printf("Array Size: %d\n", results->n);
    printf("Comparisons: %d\n", results->comparisons);
    printf("Swaps: %d\n", results->swaps);
    printf("\n");
}

int main() {
    int arr1[MAX_ARRAY_SIZE], arr2[MAX_ARRAY_SIZE];
    int n1, n2;
    BenchmarkResult results1, results2;

    /* Generate random arrays for QuickSort */
    benchmark(100, arr1, &results1, &results1.comparisons);
    benchmark(1000, arr2, &results2, &results2.comparisons);
    benchmark(10000, arr1, &results1, &results1.comparisons);
    benchmark(10000, arr2, &results2, &results2.comparisons);

    /* Print results in a table */
    print_results(&results1);
    print_results(&results2);

    return 0;
}
```

### Key Changes:

1. **Reusability**: The `benchmark()` function now encapsulates the timing logic for generating arrays and running the benchmark. It can be called multiple times with different array sizes.
2. **Output Format**: The output format remains identical to the previous version, ensuring consistency.
3. **Encapsulation**: The timing logic is now separated from the main sorting logic, making the code cleaner and easier to maintain.

